BB%85n%20Tr%C3%A3i%20C%C3%A1i%20Nhum%20V%C4%A9nh%20Long&query_place_id=ChIJXwYCCwd1oDERcrg1U0GIJwA","verification_note":"Nguồn bản đồ có tên và số nhà, chưa ghé."},{"district":"Huyện Mang Thít","name":"Văn phòng phẩm Vinh Nghi","address_line":"Khu vực thị trấn Cái Nhum cũ, huyện Mang Thít (Plus Code 643P+8WG)","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"gmap:ChIJV5jHUAB1oDERuwlZFAOwB-8","source_url":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20Vinh%20Nghi%20C%C3%A1i%20Nhum%20V%C4%A9nh%20Long&query_place_id=ChIJV5jHUAB1oDERuwlZFAOwB-8","verification_note":"Chỉ có Plus Code, chưa rõ có cửa hàng bán lẻ hay đầu mối cung cấp VPP."},{"district":"Huyện Mang Thít","name":"Cơ sở mua bán VPP Thanh Tiến","address_line":"Tổ 08, ấp Nhì A, xã Chánh Hội cũ, huyện Mang Thít","category":"van_phong_pham","phone":"0939947288","tax_code":"1500993911","source_key":"tax:1500993911:thanhtien","source_url":"https://thongtindoanhnghiep.co/1500993911-co-so-mua-ban-van-phong-pham-thanh-tien","verification_note":"Hồ sơ đăng ký kinh doanh có VPP; bản đồ ghi điểm gần Cái Nhum, chưa xác nhận cùng địa điểm bán lẻ."},{"district":"Huyện Mang Thít","name":"Nhà sách Xuân Hằng","address_line":"Khu vực xã Bình Phước cũ, huyện Mang Thít (Plus Code 52CF+3PJ)","category":"nha_sach","phone":"0782837378","tax_code":null,"source_key":"directory:vinhlongtoplist:xuanhang:52cf3pj","source_url":"https://www.vinhlongtoplist.com/top-10-nha-sach-tai-vinh-long-day-du-the-loai-gia-tot/","verification_note":"Danh bạ điểm sách; thiếu số nhà, cần xác minh vị trí."},{"district":"Huyện Mang Thít","name":"Cơ sở bán VPP Thúy Vy","address_line":"36 tổ 09, ấp Thanh Bình, xã Tân Long cũ, huyện Mang Thít","category":"van_phong_pham","phone":null,"tax_code":"1500969891","source_key":"tax:1500969891:thuyvy","source_url":"https://thongtindoanhnghiep.co/1500969891-co-so-ban-van-phong-pham-thuy-vy","verification_note":"Hồ sơ đăng ký kinh doanh lịch sử; chưa xác minh còn hoạt động năm 2026 hay có quầy bán lẻ."},{"district":"Huyện Mang Thít","name":"Dịch vụ văn phòng Hữu Phúc","address_line":"Tổ 14, khóm 2, thị trấn Cái Nhum cũ, huyện Mang Thít","category":"van_phong_pham","phone":null,"tax_code":null,"source_key":"directory:tratencongty:huuphuc:cainhum","source_url":"https://www.tratencongty.com/company/9297010c-dich-vu-van-phong-huu-phuc/","verification_note":"Hồ sơ doanh nghiệp kinh doanh dịch vụ văn phòng, chưa chắc có quầy VPP bán lẻ; cần gọi trước."}]'::jsonb) AS x(
   district text, name text, address_line text, category text, phone text, tax_code text,
   source_key text, source_url text, verification_note text
 )
), ins AS (
 INSERT INTO public.field_prospects(
   id,area_visit_id,owner_sub,name,address_line,province,district,category,
   phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch
 )
 SELECT
   (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
   NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,
   'Vĩnh Long',s.district,s.category,s.phone,s.tax_code,
   'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; hoạt động bán lẻ chưa xác minh thực địa. '
    ||s.verification_note||' Nguồn: '||s.source_url,
   'new','manual',s.source_key,s.source_url,'2026-11-21-vinh-long-old-wave-01-three-districts'
 FROM src s
 WHERE s.district IN ('Thành phố Vĩnh Long','Huyện Long Hồ','Huyện Mang Thít')
   AND s.source_url LIKE 'https://%'
   AND NOT EXISTS (
     SELECT 1 FROM public.customers c
     WHERE c.province='Vĩnh Long' AND c.district=s.district
     AND lower(btrim(c.name))=lower(btrim(s.name))
   )
   AND NOT EXISTS (
     SELECT 1 FROM public.field_prospects p
     WHERE p.province='Vĩnh Long' AND p.district=s.district
     AND (p.research_source_key=s.source_key OR
      (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line))))
   )
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,category,phone,tax_code
)
SELECT district,count(*)::int AS inserted,
 count(*) FILTER(WHERE category='nha_sach')::int AS bookstores,
 count(*) FILTER(WHERE category='van_phong_pham')::int AS stationery,
 count(*) FILTER(WHERE phone IS NOT NULL)::int AS phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int AS tax_codes
FROM ins GROUP BY district ORDER BY district;
